// NORMALIZAR ENTRADA (zona determinista)
// Toma el cuerpo del POST enviado desde Postman (chat tipo WhatsApp)
// y lo estandariza. Se aceptan varios nombres de campo por comodidad.

const body = ($input.first().json.body) || {};

const consultaRaw =
  body.consulta ?? body.opcion ?? body.mensaje ?? body.message ?? body.text ?? '';

const consulta = String(consultaRaw).trim();

return [
  {
    json: {
      consulta: consulta,
      consulta_normalizada: consulta.toLowerCase(),
      canal_origen: body.canal_origen ?? 'webhook_postman',
      // Se considera valida una seleccion o consulta con contenido real
      es_valida: consulta.length > 0
    }
  }
];

